/**
 * 门面几何（权威）：任意 key 的可视化窗口矩形 = 它的 door bbox。
 * bookKey 用 page_norm；brief/prospect/infer/query… 用 panel_norm。
 * 强调笔相对已有门的分解与基底无关——同一套 hit / blank / rel / combo。
 */

export type DoorCoordSpace = 'page_norm_0_1000' | 'panel_norm_0_1'

/** 轴对齐框；page 常为 0–1000，panel 常为 0–1 */
export type NormBBox = [number, number, number, number]
export type NormRel = [number, number, number, number]

/** 一扇门：页上 layout 槽，或注意力面板整卡 / 卡上子区 */
export type DoorFace = {
  doorKey: string
  aabb: NormBBox
  coordSpace: DoorCoordSpace
  /** 页上门：layout 步序 */
  layoutK?: number
  /** 面板子门：挂在哪扇父 key 上 */
  parentKey?: string
}

export type EmphasizeCoverage =
  | 'hit_existing'
  | 'uncovered_needs_confirm'
  | 'mixed_hit_and_uncovered'

/** 强调笔占某门 bbox 中的一块 = E ∩ D（只指针，不铸） */
export type EmphasizeOnDoorPiece = {
  doorKey: string
  layoutK?: number
  parentKey?: string
  doorAabb: NormBBox
  pieceAabb: NormBBox
  /** 门内相对位置 [u0,v0,u1,v1] ∈ [0,1]⁴ */
  rel: NormRel
  fracOfDoor: number
  fracOfEmphasize: number
}

export type EmphasizeDoorDecomposition = {
  emphasizeAabb: NormBBox
  onDoors: EmphasizeOnDoorPiece[]
  blankAabbs: NormBBox[]
  blankUnionAabb: NormBBox | null
  coverage: EmphasizeCoverage
}

export type EmphasizeReuseDoorMember = {
  kind: 'reuse'
  doorKey: string
  layoutK?: number
  parentKey?: string
  doorAabb: NormBBox
  pieceAabb: NormBBox
  rel: NormRel
}

export type EmphasizeBlankDoorMember = {
  kind: 'blank'
  aabb: NormBBox
  blankAabbs: NormBBox[]
  /** 确认后填子门 / 新 bookKey */
  doorKey?: string
  layoutK?: number
}

export type EmphasizeDoorRegionBinding = {
  emphasizeAabb: NormBBox
  coverage: EmphasizeCoverage
  reuse: EmphasizeReuseDoorMember[]
  blank: EmphasizeBlankDoorMember | null
  regionKey?: string
  regionMemberKeys: string[]
}

export const DOOR_FACE_RULE = {
  substrate: 'door_aabb_in_coord_space' as const,
  emphasizeHitsDoor: true,
  emphasizeBlankOnlyMint: true,
  emphasizeUncoveredNeedsConfirm: true,
  remintDoorOnEmphasizeStroke: false,
  /** 区域身份 = 指针∪空白新门 的 combo（或单门） */
  emphasizeRegionIsCombo: true,
} as const

/** 注意力面板默认整卡门框（panel_norm） */
export const PANEL_UNIT_DOOR: NormBBox = [0, 0, 1, 1]

export function aabbArea(b: NormBBox): number {
  return Math.max(0, b[2] - b[0]) * Math.max(0, b[3] - b[1])
}

export function aabbOverlapArea(a: NormBBox, b: NormBBox): number {
  const x0 = Math.max(a[0], b[0])
  const y0 = Math.max(a[1], b[1])
  const x1 = Math.min(a[2], b[2])
  const y1 = Math.min(a[3], b[3])
  return Math.max(0, x1 - x0) * Math.max(0, y1 - y0)
}

export function aabbIntersection(a: NormBBox, b: NormBBox): NormBBox | null {
  const x0 = Math.max(a[0], b[0])
  const y0 = Math.max(a[1], b[1])
  const x1 = Math.min(a[2], b[2])
  const y1 = Math.min(a[3], b[3])
  if (x1 <= x0 || y1 <= y0) return null
  return [x0, y0, x1, y1]
}

export function aabbUnionBounds(boxes: NormBBox[]): NormBBox | null {
  if (boxes.length === 0) return null
  let x0 = Infinity
  let y0 = Infinity
  let x1 = -Infinity
  let y1 = -Infinity
  for (const b of boxes) {
    x0 = Math.min(x0, b[0])
    y0 = Math.min(y0, b[1])
    x1 = Math.max(x1, b[2])
    y1 = Math.max(y1, b[3])
  }
  if (!(x1 > x0 && y1 > y0)) return null
  return [x0, y0, x1, y1]
}

/** piece 相对门框的归一化矩形 */
export function aabbToRelInDoor(piece: NormBBox, doorAabb: NormBBox): NormRel {
  const [bx0, by0, bx1, by1] = doorAabb
  const bw = Math.max(1e-6, bx1 - bx0)
  const bh = Math.max(1e-6, by1 - by0)
  const clamp01 = (t: number) => Math.max(0, Math.min(1, t))
  return [
    clamp01((piece[0] - bx0) / bw),
    clamp01((piece[1] - by0) / bh),
    clamp01((piece[2] - bx0) / bw),
    clamp01((piece[3] - by0) / bh),
  ]
}

/** 门框 B + rel → 反算 pieceAabb（同坐标空间） */
export function relToDoorAabb(rel: NormRel, doorAabb: NormBBox): NormBBox {
  const [bx0, by0, bx1, by1] = doorAabb
  const bw = bx1 - bx0
  const bh = by1 - by0
  return [
    bx0 + rel[0] * bw,
    by0 + rel[1] * bh,
    bx0 + rel[2] * bw,
    by0 + rel[3] * bh,
  ]
}

export function subtractOneAabb(outer: NormBBox, hole: NormBBox): NormBBox[] {
  const inter = aabbIntersection(outer, hole)
  if (!inter) return [outer]
  if (
    inter[0] <= outer[0] &&
    inter[1] <= outer[1] &&
    inter[2] >= outer[2] &&
    inter[3] >= outer[3]
  ) {
    return []
  }
  const [ox0, oy0, ox1, oy1] = outer
  const [ix0, iy0, ix1, iy1] = inter
  const out: NormBBox[] = []
  if (iy0 > oy0) out.push([ox0, oy0, ox1, iy0])
  if (iy1 < oy1) out.push([ox0, iy1, ox1, oy1])
  if (ix0 > ox0) out.push([ox0, iy0, ix0, iy1])
  if (ix1 < ox1) out.push([ix1, iy0, ox1, iy1])
  return out.filter((b) => aabbArea(b) > 1e-6)
}

export function subtractAabbs(outer: NormBBox, holes: NormBBox[]): NormBBox[] {
  let parts: NormBBox[] = [outer]
  for (const hole of holes) {
    const next: NormBBox[] = []
    for (const p of parts) next.push(...subtractOneAabb(p, hole))
    parts = next
    if (parts.length === 0) break
  }
  return parts
}

/**
 * 强调笔相对已有门集合：
 *   E = ⋃ (E ∩ door_i)  ∪  blank
 */
export function decomposeEmphasizeAgainstDoors(
  emphasizeAabb: NormBBox,
  doors: DoorFace[],
): EmphasizeDoorDecomposition {
  const eArea = Math.max(1e-6, aabbArea(emphasizeAabb))
  const onDoors: EmphasizeOnDoorPiece[] = []
  const pieceHoles: NormBBox[] = []

  for (const door of doors) {
    const piece = aabbIntersection(emphasizeAabb, door.aabb)
    if (!piece || aabbArea(piece) <= 1e-6) continue
    const doorArea = Math.max(1e-6, aabbArea(door.aabb))
    onDoors.push({
      doorKey: door.doorKey,
      layoutK: door.layoutK,
      parentKey: door.parentKey,
      doorAabb: [...door.aabb] as NormBBox,
      pieceAabb: piece,
      rel: aabbToRelInDoor(piece, door.aabb),
      fracOfDoor: aabbArea(piece) / doorArea,
      fracOfEmphasize: aabbArea(piece) / eArea,
    })
    pieceHoles.push(piece)
  }

  const blankAabbs = subtractAabbs(emphasizeAabb, pieceHoles)
  const blankUnionAabb = aabbUnionBounds(blankAabbs)
  const hasPieces = onDoors.length > 0
  const hasBlank = blankAabbs.length > 0

  let coverage: EmphasizeCoverage
  if (hasPieces && hasBlank) coverage = 'mixed_hit_and_uncovered'
  else if (hasPieces) coverage = 'hit_existing'
  else coverage = 'uncovered_needs_confirm'

  return {
    emphasizeAabb,
    onDoors,
    blankAabbs,
    blankUnionAabb,
    coverage,
  }
}

export function decompositionToDoorRegionBinding(
  d: EmphasizeDoorDecomposition,
): EmphasizeDoorRegionBinding {
  const reuse: EmphasizeReuseDoorMember[] = d.onDoors.map((p) => ({
    kind: 'reuse' as const,
    doorKey: p.doorKey,
    layoutK: p.layoutK,
    parentKey: p.parentKey,
    doorAabb: p.doorAabb,
    pieceAabb: p.pieceAabb,
    rel: p.rel,
  }))
  const blank: EmphasizeBlankDoorMember | null =
    d.blankUnionAabb && d.blankAabbs.length > 0
      ? {
          kind: 'blank',
          aabb: d.blankUnionAabb,
          blankAabbs: d.blankAabbs,
        }
      : null

  return {
    emphasizeAabb: d.emphasizeAabb,
    coverage: d.coverage,
    reuse,
    blank,
    regionMemberKeys: reuse.map((r) => r.doorKey),
  }
}

/**
 * 页上划重点共享基底（权威）：
 *
 * 纯空间：同一份未改版 PDF 的某一页（docId + page）+ page_norm bbox。
 * 时间化划重点 —— layout 与 emphasize **同级 peer**。
 *
 * 强调笔相对已有 bookKey 的分解 = 通用 DoorFace 分解（见 doorFace.ts）：
 *   emphasize.aabb
 *     = ⋃_i (emphasize ∩ bookKey_i.bbox)   ← 占该门 bbox 的哪一块（指针+rel）
 *     ∪ blank                               ← 仅空白可铸新门
 *
 * 强调笔区域身份 = combo( 指针门…, 空白新门? )，不是把整圈再铸成一门。
 * bookKey 的「门」= layout bbox；注意力面板的「门」= 可视化窗口矩形（同构）。
 */

import type { BookKeyCoord } from './bookKey'
import {
  aabbArea,
  aabbIntersection,
  aabbOverlapArea,
  aabbToRelInDoor,
  aabbUnionBounds,
  decomposeEmphasizeAgainstDoors,
  decompositionToDoorRegionBinding,
  relToDoorAabb,
  subtractAabbs,
  subtractOneAabb,
  type DoorFace,
  type EmphasizeCoverage,
  type EmphasizeDoorDecomposition,
  type NormBBox,
  type NormRel,
} from './doorFace'

export type PageNormBBox = NormBBox
export type PageNormPoint = [number, number]
/** 相对某 bookKey bbox 的门内归一化矩形 [u0,v0,u1,v1] ∈ [0,1]⁴ */
export type PageNormRel = NormRel

export type { EmphasizeCoverage }

export type PageMarkKind = 'layout' | 'emphasize'

/** 一笔划重点（layout 或强调笔）——同级时间事件 */
export type PageMark = {
  markId: string
  kind: PageMarkKind
  docId: string
  page: number
  aabb: PageNormBBox
  polygon?: PageNormPoint[]
  createdAt: number
  layoutK?: number
  /** layout 槽门牌；或强调笔挂上的空白新门 / 单指针门 */
  bookKey?: string
  /**
   * 强调笔区域把手：单门或 combo(指针∪空白新门)。
   * 有 regionKey 时以它为「这一圈」的身份；bookKey 可能只是 blank 成员。
   */
  regionKey?: string
  regionMemberKeys?: string[]
}

/** 强调笔占某个已有 bookKey 的 bbox 中的哪一块 = E ∩ B（只指针，不铸） */
export type EmphasizeOnBookKeyPiece = {
  bookKey: string
  layoutK?: number
  /** 该 bookKey 的完整 bbox */
  bookKeyAabb: PageNormBBox
  /** 强调笔在该门上的占块（page_norm） */
  pieceAabb: PageNormBBox
  /** 门内相对位置：机器可读，反算回 page */
  rel: PageNormRel
  /** piece 占 bookKey 面积比（不能单独定位） */
  fracOfBookKey: number
  /** piece 占强调笔面积比 */
  fracOfEmphasize: number
}

/** 区域成员：指回已有门（带门内块） */
export type EmphasizeReuseMember = {
  kind: 'reuse'
  bookKey: string
  layoutK?: number
  bookKeyAabb: PageNormBBox
  pieceAabb: PageNormBBox
  rel: PageNormRel
}

/** 区域成员：空白新门（确认后填 bookKey） */
export type EmphasizeBlankMember = {
  kind: 'blank'
  aabb: PageNormBBox
  blankAabbs: PageNormBBox[]
  bookKey?: string
  layoutK?: number
}

export type EmphasizeRegionMember = EmphasizeReuseMember | EmphasizeBlankMember

/**
 * 强调笔区域绑定：
 * 指针成员 +（可选）空白铸门 → 合成 regionKey（combo 或单门）
 */
export type EmphasizeRegionBinding = {
  emphasizeAabb: PageNormBBox
  coverage: EmphasizeCoverage
  reuse: EmphasizeReuseMember[]
  blank: EmphasizeBlankMember | null
  /** 已齐（无待确认空白，或空白已铸）时的区域把手 */
  regionKey?: string
  regionMemberKeys: string[]
}

/** 强调笔 bbox 的完整分解 */
export type EmphasizeAabbDecomposition = {
  emphasizeAabb: PageNormBBox
  onBookKeys: EmphasizeOnBookKeyPiece[]
  blankAabbs: PageNormBBox[]
  blankUnionAabb: PageNormBBox | null
  coverage: EmphasizeCoverage
}

export const PAGE_MARK_RULE = {
  substrate: 'docId+page+page_norm_bbox' as const,
  peers: ['layout', 'emphasize'] as const,
  mintFormula: 'layout_coord_seal' as const,
  layoutAutoMint: true,
  emphasizeHitsLayout: true,
  /** 仅空白可铸；占块只指针 */
  emphasizeBlankOnlyMint: true,
  emphasizeUncoveredNeedsConfirm: true,
  emphasizeMixedDecompose: true,
  /** 区域身份 = 指针∪空白新门 的 combo（或单门） */
  emphasizeRegionIsCombo: true,
  remintBookKeyOnEmphasizeStroke: false,
  /** 门面几何与注意力面板同构（doorFace） */
  doorFaceIsomorphic: true,
} as const

export {
  aabbArea,
  aabbIntersection,
  aabbOverlapArea,
  aabbUnionBounds,
  subtractAabbs,
  subtractOneAabb,
}

/** @deprecated 用 aabbToRelInDoor；保留 book 语义别名 */
export function aabbToRelInBookKey(
  piece: PageNormBBox,
  bookKeyAabb: PageNormBBox,
): PageNormRel {
  return aabbToRelInDoor(piece, bookKeyAabb)
}

/** @deprecated 用 relToDoorAabb */
export function relToPageAabb(
  rel: PageNormRel,
  bookKeyAabb: PageNormBBox,
): PageNormBBox {
  return relToDoorAabb(rel, bookKeyAabb)
}

export type LayoutSlotGeom = {
  bookKey: string
  aabb: PageNormBBox
  layoutK?: number
}

function slotsToDoors(slots: LayoutSlotGeom[]): DoorFace[] {
  return slots.map((s) => ({
    doorKey: s.bookKey,
    aabb: s.aabb,
    coordSpace: 'page_norm_0_1000' as const,
    layoutK: s.layoutK,
  }))
}

function doorDecompToBook(
  d: EmphasizeDoorDecomposition,
): EmphasizeAabbDecomposition {
  return {
    emphasizeAabb: d.emphasizeAabb,
    onBookKeys: d.onDoors.map((p) => ({
      bookKey: p.doorKey,
      layoutK: p.layoutK,
      bookKeyAabb: p.doorAabb,
      pieceAabb: p.pieceAabb,
      rel: p.rel,
      fracOfBookKey: p.fracOfDoor,
      fracOfEmphasize: p.fracOfEmphasize,
    })),
    blankAabbs: d.blankAabbs,
    blankUnionAabb: d.blankUnionAabb,
    coverage: d.coverage,
  }
}

/** 页上 layout 槽 = DoorFace；分解委托 doorFace（效果不变） */
export function decomposeEmphasizeAabbAgainstLayout(
  emphasizeAabb: PageNormBBox,
  slots: LayoutSlotGeom[],
): EmphasizeAabbDecomposition {
  return doorDecompToBook(
    decomposeEmphasizeAgainstDoors(emphasizeAabb, slotsToDoors(slots)),
  )
}

/** 分解 → 区域绑定草稿（空白未铸则无 regionKey） */
export function decompositionToRegionBinding(
  d: EmphasizeAabbDecomposition,
): EmphasizeRegionBinding {
  const asDoor: EmphasizeDoorDecomposition = {
    emphasizeAabb: d.emphasizeAabb,
    onDoors: d.onBookKeys.map((p) => ({
      doorKey: p.bookKey,
      layoutK: p.layoutK,
      doorAabb: p.bookKeyAabb,
      pieceAabb: p.pieceAabb,
      rel: p.rel,
      fracOfDoor: p.fracOfBookKey,
      fracOfEmphasize: p.fracOfEmphasize,
    })),
    blankAabbs: d.blankAabbs,
    blankUnionAabb: d.blankUnionAabb,
    coverage: d.coverage,
  }
  const b = decompositionToDoorRegionBinding(asDoor)
  return {
    emphasizeAabb: b.emphasizeAabb,
    coverage: b.coverage,
    reuse: b.reuse.map((r) => ({
      kind: 'reuse' as const,
      bookKey: r.doorKey,
      layoutK: r.layoutK,
      bookKeyAabb: r.doorAabb,
      pieceAabb: r.pieceAabb,
      rel: r.rel,
    })),
    blank: b.blank
      ? {
          kind: 'blank' as const,
          aabb: b.blank.aabb,
          blankAabbs: b.blank.blankAabbs,
          bookKey: b.blank.doorKey,
          layoutK: b.blank.layoutK,
        }
      : null,
    regionKey: b.regionKey,
    regionMemberKeys: b.regionMemberKeys,
  }
}

export function layoutMarkId(coord: BookKeyCoord): string {
  return `mark_layout_p${coord.page}_k${coord.layoutK}`
}

export function makeLayoutPageMark(input: {
  docId: string
  page: number
  layoutK: number
  aabb: PageNormBBox
  bookKey: string
  createdAt?: number
}): PageMark {
  const coord = {
    docId: input.docId,
    page: input.page,
    layoutK: input.layoutK,
  }
  return {
    markId: layoutMarkId(coord),
    kind: 'layout',
    docId: input.docId,
    page: input.page,
    aabb: input.aabb,
    layoutK: input.layoutK,
    bookKey: input.bookKey,
    createdAt: input.createdAt ?? Date.now(),
  }
}

export function makeEmphasizePageMark(input: {
  markId: string
  docId: string
  page: number
  aabb: PageNormBBox
  polygon?: PageNormPoint[]
  createdAt?: number
  bookKey?: string
  layoutK?: number
  regionKey?: string
  regionMemberKeys?: string[]
}): PageMark {
  return {
    markId: input.markId,
    kind: 'emphasize',
    docId: input.docId,
    page: input.page,
    aabb: input.aabb,
    polygon: input.polygon,
    createdAt: input.createdAt ?? Date.now(),
    bookKey: input.bookKey,
    layoutK: input.layoutK,
    regionKey: input.regionKey,
    regionMemberKeys: input.regionMemberKeys,
  }
}

/** bookKey layout 槽 → DoorFace（供面板/页统一调用） */
export function layoutSlotAsDoorFace(slot: LayoutSlotGeom): DoorFace {
  return {
    doorKey: slot.bookKey,
    aabb: slot.aabb,
    coordSpace: 'page_norm_0_1000',
    layoutK: slot.layoutK,
  }
}

/**
 * 注意力面板 = 任意 key 的可视化门面。
 * 面板矩形（panel_norm）对强调笔而言 = bookKey 的 layout bbox。
 *
 * 壳层：按 key 类型落位；绝对半径 = 总尺度 × 相对比例（可等比例缩放）。
 * 实例坐标在调取时现算；不预先铺满所有 key。
 */

import {
  PANEL_UNIT_DOOR,
  type DoorFace,
  type NormBBox,
} from './doorFace'

export type AttentionKeyKind =
  | 'book'
  | 'brief'
  | 'prospect'
  | 'infer'
  | 'query'
  | 'path'
  | 'neighbour'
  | 'reuse'
  | 'other'

/**
 * 相对内球的壳比例（固定比；总尺度另乘）。
 * book 贴内页；其余由内向外。
 */
export const KEY_SHELL_RATIO: Record<AttentionKeyKind, number> = {
  book: 1,
  brief: 1.22,
  prospect: 1.48,
  infer: 1.8,
  path: 1.8,
  neighbour: 2.05,
  reuse: 2.05,
  query: 2.2,
  other: 1.35,
}

export type AttentionPanel = {
  /** 面板门牌 = 该 key */
  key: string
  keyKind: AttentionKeyKind
  /** 可读正文（窗上效果） */
  faceText: string
  /**
   * 门 bbox（panel_norm）。默认整卡 [0,0,1,1]；
   * 子区确认后可挂更小的门。
   */
  doorAabb: NormBBox
  /** 材料挂靠（非 book 时用于径向锚点） */
  hostBookKey?: string
  queryKey?: string
  createdAt: number
}

export function makeAttentionPanel(input: {
  key: string
  keyKind: AttentionKeyKind
  faceText: string
  doorAabb?: NormBBox
  hostBookKey?: string
  queryKey?: string
  createdAt?: number
}): AttentionPanel {
  return {
    key: input.key,
    keyKind: input.keyKind,
    faceText: input.faceText,
    doorAabb: input.doorAabb ?? [...PANEL_UNIT_DOOR],
    hostBookKey: input.hostBookKey,
    queryKey: input.queryKey,
    createdAt: input.createdAt ?? Date.now(),
  }
}

/** 面板整门 → DoorFace（强调笔同构） */
export function panelAsDoorFace(panel: AttentionPanel): DoorFace {
  return {
    doorKey: panel.key,
    aabb: panel.doorAabb,
    coordSpace: 'panel_norm_0_1',
    parentKey: panel.hostBookKey,
  }
}

/** 面板上已确认的子门（空白铸区，不铸 bookKey） */
export function panelChildDoorFace(input: {
  parentKey: string
  childKey: string
  aabb: NormBBox
  layoutK?: number
}): DoorFace {
  return {
    doorKey: input.childKey,
    aabb: input.aabb,
    coordSpace: 'panel_norm_0_1',
    parentKey: input.parentKey,
    layoutK: input.layoutK,
  }
}

export function shellRadiusForKind(
  kind: AttentionKeyKind,
  innerRadius: number,
  globalScale = 1,
): number {
  const ratio = KEY_SHELL_RATIO[kind] ?? KEY_SHELL_RATIO.other
  return Math.max(1e-6, innerRadius * ratio * globalScale)
}

/**
 * 由宿主书上世界点沿径向推到该类壳 → 面板锚点。
 * book 类直接用 host 点（乘 book 比例≈1）。
 */
export function panelWorldAnchorFromHost(
  hostWorld: [number, number, number],
  kind: AttentionKeyKind,
  innerRadius: number,
  globalScale = 1,
): [number, number, number] {
  const len =
    Math.hypot(hostWorld[0], hostWorld[1], hostWorld[2]) || innerRadius
  const targetR = shellRadiusForKind(kind, innerRadius, globalScale)
  const s = targetR / len
  return [hostWorld[0] * s, hostWorld[1] * s, hostWorld[2] * s]
}

export function newPanelChildDoorKey(parentKey: string, k: number): string {
  return `${parentKey}|panel|k${k}`
}

/**
 * 注意力面板上的强调笔：与页上 bookKey 同构。
 * 门 = 面板 doorAabb（+ 已确认子门）；命中只指针；空白须确认后铸面板子门（不铸 bookKey）。
 */

import { create } from 'zustand'
import {
  decomposeEmphasizeAgainstDoors,
  decompositionToDoorRegionBinding,
  type EmphasizeCoverage,
  type EmphasizeDoorDecomposition,
  type EmphasizeDoorRegionBinding,
  type NormBBox,
  type DoorFace,
} from '../arch/doorFace'
import {
  newPanelChildDoorKey,
  panelAsDoorFace,
  panelChildDoorFace,
  type AttentionPanel,
} from '../arch/attentionPanel'

export type PanelEmphasizeStroke = {
  id: string
  panelKey: string
  aabb: NormBBox
  createdAt: number
  coverage: EmphasizeCoverage
  decomposition: EmphasizeDoorDecomposition
  binding: EmphasizeDoorRegionBinding
  /** 空白确认后挂上的子门 */
  blankDoorKey?: string
}

type PanelEmphasizeState = {
  /** panelKey → 已确认子门（空白铸） */
  childDoorsByPanel: Record<string, DoorFace[]>
  strokes: PanelEmphasizeStroke[]
  pendingBlank: {
    strokeId: string
    panelKey: string
    aabb: NormBBox
  } | null
  lastCoverage: EmphasizeCoverage | null
  lastBinding: EmphasizeDoorRegionBinding | null

  doorsForPanel: (panel: AttentionPanel) => DoorFace[]
  /** 落一笔（panel_norm aabb）→ 分解，效果同页上强调笔 */
  sealStroke: (input: {
    panel: AttentionPanel
    aabb: NormBBox
  }) => PanelEmphasizeStroke
  /** 空白确认 → 铸面板子门（挂 parentKey，不当 bookKey） */
  confirmBlankChildDoor: (input: {
    panel: AttentionPanel
    confirm: true
  }) => { ok: true; doorKey: string } | { ok: false; note: string }
  clearPending: () => void
  clearPanel: (panelKey: string) => void
}

function sid(): string {
  return `pem_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 6)}`
}

export const usePanelEmphasizeStore = create<PanelEmphasizeState>(
  (set, get) => ({
    childDoorsByPanel: {},
    strokes: [],
    pendingBlank: null,
    lastCoverage: null,
    lastBinding: null,

    doorsForPanel: (panel) => {
      const main = panelAsDoorFace(panel)
      const kids = get().childDoorsByPanel[panel.key] ?? []
      // 子门优先命中：分解时多门并列；主门仍在，占块可落主门或子门
      return [main, ...kids]
    },

    sealStroke: ({ panel, aabb }) => {
      const doors = get().doorsForPanel(panel)
      const decomposition = decomposeEmphasizeAgainstDoors(aabb, doors)
      const binding = decompositionToDoorRegionBinding(decomposition)
      const stroke: PanelEmphasizeStroke = {
        id: sid(),
        panelKey: panel.key,
        aabb,
        createdAt: Date.now(),
        coverage: decomposition.coverage,
        decomposition,
        binding,
      }

      const needsConfirm =
        decomposition.coverage === 'uncovered_needs_confirm' ||
        decomposition.coverage === 'mixed_hit_and_uncovered'

      set((s) => ({
        strokes: [...s.strokes, stroke],
        lastCoverage: decomposition.coverage,
        lastBinding: binding,
        pendingBlank:
          needsConfirm && binding.blank
            ? {
                strokeId: stroke.id,
                panelKey: panel.key,
                aabb: binding.blank.aabb,
              }
            : null,
      }))
      return stroke
    },

    confirmBlankChildDoor: ({ panel, confirm }) => {
      if (confirm !== true) {
        return { ok: false, note: '须 confirm:true' }
      }
      const pending = get().pendingBlank
      if (!pending || pending.panelKey !== panel.key) {
        return { ok: false, note: '无匹配的面板空白待确认' }
      }
      const existing = get().childDoorsByPanel[panel.key] ?? []
      const k = existing.length
      const doorKey = newPanelChildDoorKey(panel.key, k)
      const child = panelChildDoorFace({
        parentKey: panel.key,
        childKey: doorKey,
        aabb: pending.aabb,
        layoutK: k,
      })
      set((s) => ({
        childDoorsByPanel: {
          ...s.childDoorsByPanel,
          [panel.key]: [...existing, child],
        },
        strokes: s.strokes.map((st) =>
          st.id === pending.strokeId
            ? {
                ...st,
                blankDoorKey: doorKey,
                binding: {
                  ...st.binding,
                  blank: st.binding.blank
                    ? { ...st.binding.blank, doorKey, layoutK: k }
                    : null,
                  regionMemberKeys: [
                    ...st.binding.regionMemberKeys,
                    doorKey,
                  ],
                },
              }
            : st,
        ),
        pendingBlank: null,
      }))
      return { ok: true, doorKey }
    },

    clearPending: () => set({ pendingBlank: null }),

    clearPanel: (panelKey) =>
      set((s) => {
        const { [panelKey]: _, ...rest } = s.childDoorsByPanel
        return {
          childDoorsByPanel: rest,
          strokes: s.strokes.filter((st) => st.panelKey !== panelKey),
          pendingBlank:
            s.pendingBlank?.panelKey === panelKey ? null : s.pendingBlank,
        }
      }),
  }),
)

/**
 * 注意力门面可画区：在 panel_norm 上拖矩形圈选，
 * 分解逻辑与页上 bookKey 强调笔一致（命中 / 空白 / rel）。
 */

import { useCallback, useMemo, useRef, useState, type ReactNode } from 'react'
import {
  makeAttentionPanel,
  type AttentionKeyKind,
} from '../arch/attentionPanel'
import type { NormBBox } from '../arch/doorFace'
import { usePanelEmphasizeStore } from '../reasoning/panelEmphasizeStore'

function coverageLabel(
  c: 'hit_existing' | 'uncovered_needs_confirm' | 'mixed_hit_and_uncovered',
): string {
  if (c === 'hit_existing') return '命中已有门 · 只指针+rel，不铸'
  if (c === 'uncovered_needs_confirm') return '空白 · 须确认后铸面板子门'
  return '混合 · 占块复用 + 空白待确认'
}

function bboxStyle(b: NormBBox): React.CSSProperties {
  const [x0, y0, x1, y1] = b
  return {
    left: `${x0 * 100}%`,
    top: `${y0 * 100}%`,
    width: `${Math.max(0, x1 - x0) * 100}%`,
    height: `${Math.max(0, y1 - y0) * 100}%`,
  }
}

export function AttentionDoorFace({
  doorKey,
  keyKind,
  faceText,
  hostBookKey,
  queryKey,
  children,
  enabled = true,
}: {
  doorKey: string
  keyKind: AttentionKeyKind
  faceText: string
  hostBookKey?: string
  queryKey?: string
  children: ReactNode
  /** false = 只展示不圈画（折叠 chip 等） */
  enabled?: boolean
}) {
  const rootRef = useRef<HTMLDivElement>(null)
  const drawing = useRef(false)
  const origin = useRef<{ x: number; y: number } | null>(null)
  const [draft, setDraft] = useState<NormBBox | null>(null)

  const sealStroke = usePanelEmphasizeStore((s) => s.sealStroke)
  const confirmBlank = usePanelEmphasizeStore((s) => s.confirmBlankChildDoor)
  const pendingBlank = usePanelEmphasizeStore((s) => s.pendingBlank)
  const strokes = usePanelEmphasizeStore((s) => s.strokes)
  const childDoors = usePanelEmphasizeStore(
    (s) => s.childDoorsByPanel[doorKey] ?? [],
  )

  const panel = useMemo(
    () =>
      makeAttentionPanel({
        key: doorKey,
        keyKind,
        faceText,
        hostBookKey,
        queryKey,
      }),
    [doorKey, keyKind, faceText, hostBookKey, queryKey],
  )

  const mine = strokes.filter((st) => st.panelKey === doorKey)
  const last = mine[mine.length - 1] ?? null
  const pendingHere =
    pendingBlank?.panelKey === doorKey ? pendingBlank : null

  const clientToNorm = useCallback((clientX: number, clientY: number) => {
    const el = rootRef.current
    if (!el) return null
    const r = el.getBoundingClientRect()
    if (r.width < 1 || r.height < 1) return null
    const u = Math.max(0, Math.min(1, (clientX - r.left) / r.width))
    const v = Math.max(0, Math.min(1, (clientY - r.top) / r.height))
    return { u, v }
  }, [])

  const onPointerDown = (e: React.PointerEvent) => {
    if (!enabled) return
    // 仅左键；让按钮自己点
    if (e.button !== 0) return
    const t = e.target as HTMLElement
    if (t.closest('button, a, input, textarea')) return
    const p = clientToNorm(e.clientX, e.clientY)
    if (!p) return
    e.preventDefault()
    e.stopPropagation()
    drawing.current = true
    origin.current = { x: p.u, y: p.v }
    setDraft([p.u, p.v, p.u, p.v])
    rootRef.current?.setPointerCapture(e.pointerId)
  }

  const onPointerMove = (e: React.PointerEvent) => {
    if (!drawing.current || !origin.current) return
    const p = clientToNorm(e.clientX, e.clientY)
    if (!p) return
    const o = origin.current
    setDraft([
      Math.min(o.x, p.u),
      Math.min(o.y, p.v),
      Math.max(o.x, p.u),
      Math.max(o.y, p.v),
    ])
  }

  const finish = (e: React.PointerEvent) => {
    if (!drawing.current) return
    drawing.current = false
    origin.current = null
    try {
      rootRef.current?.releasePointerCapture(e.pointerId)
    } catch {
      /* */
    }
    setDraft((d) => {
      if (!d) return null
      const area = Math.max(0, d[2] - d[0]) * Math.max(0, d[3] - d[1])
      if (area < 0.0004) return null
      sealStroke({ panel, aabb: d })
      return null
    })
  }

  return (
    <div
      ref={rootRef}
      className={`attn-door-face${enabled ? ' attn-door-face-live' : ''}`}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={finish}
      onPointerCancel={finish}
    >
      <div className="attn-door-face-body">{children}</div>

      <div className="attn-door-face-overlay" aria-hidden>
        {childDoors.map((d) => (
          <div
            key={d.doorKey}
            className="attn-door-child"
            style={bboxStyle(d.aabb)}
            title={`子门 ${d.doorKey}`}
          />
        ))}
        {mine.map((st) =>
          st.decomposition.onDoors.map((p, i) => (
            <div
              key={`${st.id}_hit_${i}`}
              className="attn-door-hit"
              style={bboxStyle(p.pieceAabb)}
              title={`命中 ${p.doorKey} · rel=${p.rel.map((n) => n.toFixed(2)).join(',')}`}
            />
          )),
        )}
        {mine.map((st) =>
          st.decomposition.blankAabbs.map((b, i) => (
            <div
              key={`${st.id}_blank_${i}`}
              className="attn-door-blank"
              style={bboxStyle(b)}
              title="空白 · 待确认铸子门"
            />
          )),
        )}
        {draft && (
          <div className="attn-door-draft" style={bboxStyle(draft)} />
        )}
      </div>

      {enabled && (
        <div className="attn-door-face-status" role="status">
          {last ? (
            <>
              <span>{coverageLabel(last.coverage)}</span>
              {last.decomposition.onDoors[0] && (
                <span className="attn-door-meta">
                  · rel[
                  {last.decomposition.onDoors[0].rel
                    .map((n) => n.toFixed(2))
                    .join(',')}
                  ]
                </span>
              )}
              {pendingHere && (
                <button
                  type="button"
                  className="attn-door-confirm"
                  onClick={(ev) => {
                    ev.stopPropagation()
                    confirmBlank({ panel, confirm: true })
                  }}
                >
                  确认铸子门
                </button>
              )}
            </>
          ) : (
            <span>在窗上拖矩形 = 强调笔（与 bookKey 门同构）</span>
          )}
        </div>
      )}
    </div>
  )
}

