/**
 * 被调取的注意力面板（常显，非 chip 点开窗）。
 * 只存「要亮哪些 key」；世界坐标现算（keyWorldAnchor）。
 */

import { create } from 'zustand'
import type { AttentionKeyKind } from '../arch/attentionPanel'
import { inferAttentionKeyKind } from './keyWorldAnchor'

export type SummonedPanel = {
  key: string
  keyKind: AttentionKeyKind
  summonedAt: number
}

type PanelSummonState = {
  panels: SummonedPanel[]
  globalScale: number
  setGlobalScale: (s: number) => void
  /** 调取：已有则刷新时间；可一次多个 */
  summonKeys: (keys: string[]) => void
  dismissKey: (key: string) => void
  dismissAll: () => void
  has: (key: string) => boolean
}

export const usePanelSummonStore = create<PanelSummonState>((set, get) => ({
  panels: [],
  globalScale: 1,
  setGlobalScale: (s) => set({ globalScale: Math.max(0.35, Math.min(3, s)) }),

  summonKeys: (keys) => {
    const now = Date.now()
    set((s) => {
      const map = new Map(s.panels.map((p) => [p.key, p]))
      for (const raw of keys) {
        const key = raw.trim()
        if (!key) continue
        map.set(key, {
          key,
          keyKind: inferAttentionKeyKind(key),
          summonedAt: now,
        })
      }
      return { panels: [...map.values()] }
    })
  },

  dismissKey: (key) =>
    set((s) => ({ panels: s.panels.filter((p) => p.key !== key) })),

  dismissAll: () => set({ panels: [] }),

  has: (key) => get().panels.some((p) => p.key === key),
}))

/**
 * 常显 key 面板层：锚点处立可读门面（像页一样直接看见，不点开）。
 */

import { Html } from '@react-three/drei'
import { useMemo } from 'react'
import { useIndexGate } from '../reasoning/indexGate'
import { useDocuverse } from './store'
import { usePanelSummonStore } from '../reasoning/panelSummonStore'
import { resolveKeyWorldAnchor } from '../reasoning/keyWorldAnchor'
import { AttentionDoorFace } from '../ui/AttentionDoorFace'
import { shortHandle } from '../reasoning/ocrSlot'

export function KeyPanelLayer() {
  const panels = usePanelSummonStore((s) => s.panels)
  const globalScale = usePanelSummonStore((s) => s.globalScale)
  const dismissKey = usePanelSummonStore((s) => s.dismissKey)
  const bookIndex = useIndexGate((s) => s.bookIndex)
  const pageCount = useDocuverse((s) => Math.max(s.pages.length, 1))

  const resolved = useMemo(() => {
    if (!bookIndex || panels.length === 0) return []
    return panels.map((p) => {
      const a = resolveKeyWorldAnchor({
        key: p.key,
        keyKind: p.keyKind,
        bookIndex,
        pageCount,
        globalScale,
      })
      return { summoned: p, anchor: a }
    })
  }, [bookIndex, panels, pageCount, globalScale])

  if (!bookIndex || resolved.length === 0) return null

  return (
    <group>
      {resolved.map(({ summoned, anchor }) => {
        if (!anchor.world) return null
        return (
          <Html
            key={summoned.key}
            position={anchor.world}
            center
            distanceFactor={18}
            zIndexRange={[160, 0]}
            style={{ pointerEvents: 'auto' }}
          >
            <div
              className="key-panel-live"
              data-kind={anchor.keyKind}
              onPointerDown={(e) => e.stopPropagation()}
            >
              <div className="key-panel-live-head">
                <span className="key-panel-live-kind">{anchor.keyKind}</span>
                <span className="key-panel-live-id" title={anchor.key}>
                  {shortHandle(anchor.key)}
                </span>
                <button
                  type="button"
                  className="key-panel-live-x"
                  title="收起"
                  onClick={() => dismissKey(summoned.key)}
                >
                  ×
                </button>
              </div>
              <AttentionDoorFace
                doorKey={anchor.key}
                keyKind={anchor.keyKind}
                faceText={anchor.faceText}
                hostBookKey={anchor.hostBookKey ?? undefined}
                queryKey={
                  anchor.keyKind === 'query' ? anchor.key : undefined
                }
              >
                <div className="key-panel-live-body">
                  {anchor.faceText.trim() || (
                    <span className="key-panel-live-empty">（无正文）</span>
                  )}
                </div>
              </AttentionDoorFace>
              {!anchor.ok && (
                <div className="key-panel-live-warn">{anchor.note}</div>
              )}
            </div>
          </Html>
        )
      })}
    </group>
  )
}

