/**
 * 注意力面板 = 任意 key 的可视化门面。
 * 面板矩形（panel_norm）对强调笔而言 = bookKey 的 layout bbox。
 *
 * 壳层半径（产品规则）：
 * - KEY_KIND_ORDER 只定「谁在谁外」的层序，不当绝对距离。
 * - 实际半径只按**当前已调取**的类型挤成相邻壳；未调取的中间层当作不存在。
 * - 例如只亮 book + query → 两层相邻，不会一个贴内球一个飞到最外。
 * - 再加入 brief（夹在中间）→ 重排为三层相邻。
 * - globalScale 等比例缩放整簇。
 */

import {
  PANEL_UNIT_DOOR,
  type DoorFace,
  type NormBBox,
} from './doorFace'

export type AttentionKeyKind =
  | 'book'
  | 'brief'
  | 'prospect'
  | 'infer'
  | 'query'
  | 'path'
  | 'neighbour'
  | 'reuse'
  | 'other'

/** 层序（内→外）；只排序，不决定间距 */
export const KEY_KIND_ORDER: AttentionKeyKind[] = [
  'book',
  'brief',
  'prospect',
  'other',
  'infer',
  'path',
  'neighbour',
  'reuse',
  'query',
]

/**
 * @deprecated 绝对比例表；布局请用 packAdjacentShellRatios。
 * 保留作文档/旧调用对照。
 */
export const KEY_SHELL_RATIO: Record<AttentionKeyKind, number> = {
  book: 1,
  brief: 1.22,
  prospect: 1.48,
  infer: 1.8,
  path: 1.8,
  neighbour: 2.05,
  reuse: 2.05,
  query: 2.2,
  other: 1.35,
}

/** 相邻两层之间的固定步长（相对内球半径） */
export const ADJACENT_SHELL_STEP = 0.18

export type AttentionPanel = {
  /** 面板门牌 = 该 key */
  key: string
  keyKind: AttentionKeyKind
  /** 可读正文（窗上效果） */
  faceText: string
  /**
   * 门 bbox（panel_norm）。默认整卡 [0,0,1,1]；
   * 子区确认后可挂更小的门。
   */
  doorAabb: NormBBox
  /** 材料挂靠（非 book 时用于径向锚点） */
  hostBookKey?: string
  queryKey?: string
  createdAt: number
}

export function makeAttentionPanel(input: {
  key: string
  keyKind: AttentionKeyKind
  faceText: string
  doorAabb?: NormBBox
  hostBookKey?: string
  queryKey?: string
  createdAt?: number
}): AttentionPanel {
  return {
    key: input.key,
    keyKind: input.keyKind,
    faceText: input.faceText,
    doorAabb: input.doorAabb ?? [...PANEL_UNIT_DOOR],
    hostBookKey: input.hostBookKey,
    queryKey: input.queryKey,
    createdAt: input.createdAt ?? Date.now(),
  }
}

/** 面板整门 → DoorFace（强调笔同构） */
export function panelAsDoorFace(panel: AttentionPanel): DoorFace {
  return {
    doorKey: panel.key,
    aabb: panel.doorAabb,
    coordSpace: 'panel_norm_0_1',
    parentKey: panel.hostBookKey,
  }
}

/** 面板上已确认的子门（空白铸区，不铸 bookKey） */
export function panelChildDoorFace(input: {
  parentKey: string
  childKey: string
  aabb: NormBBox
  layoutK?: number
}): DoorFace {
  return {
    doorKey: input.childKey,
    aabb: input.aabb,
    coordSpace: 'panel_norm_0_1',
    parentKey: input.parentKey,
    layoutK: input.layoutK,
  }
}

export function kindOrderIndex(kind: AttentionKeyKind): number {
  const i = KEY_KIND_ORDER.indexOf(kind)
  return i >= 0 ? i : KEY_KIND_ORDER.indexOf('other')
}

/**
 * 只对「当前在场」的类型打包相邻壳半径比。
 * 未出现的中间类型不占位 → book 与 query 单独在场时相邻。
 */
export function packAdjacentShellRatios(
  activeKinds: AttentionKeyKind[],
  step = ADJACENT_SHELL_STEP,
): Map<AttentionKeyKind, number> {
  const uniq = [...new Set(activeKinds)]
  uniq.sort((a, b) => kindOrderIndex(a) - kindOrderIndex(b))
  const map = new Map<AttentionKeyKind, number>()
  uniq.forEach((kind, i) => {
    map.set(kind, 1 + i * step)
  })
  return map
}

/** 某类型在当前在场集合下的半径比；无集合时退回单层=1（贴宿主） */
export function adjacentRatioForKind(
  kind: AttentionKeyKind,
  activeKinds?: AttentionKeyKind[],
  step = ADJACENT_SHELL_STEP,
): number {
  if (!activeKinds || activeKinds.length === 0) {
    // 单独一个 key：就站在「第 0 外层」——book 用 1，其它也用 1+step 以免与页重叠
    return kind === 'book' ? 1 : 1 + step
  }
  const packed = packAdjacentShellRatios(activeKinds, step)
  return packed.get(kind) ?? (kind === 'book' ? 1 : 1 + step)
}

export function shellRadiusForKind(
  kind: AttentionKeyKind,
  innerRadius: number,
  globalScale = 1,
  activeKinds?: AttentionKeyKind[],
): number {
  const ratio = adjacentRatioForKind(kind, activeKinds)
  return Math.max(1e-6, innerRadius * ratio * globalScale)
}

/**
 * 由宿主书上世界点沿径向推到「当前打包壳」→ 面板锚点。
 */
export function panelWorldAnchorFromHost(
  hostWorld: [number, number, number],
  kind: AttentionKeyKind,
  innerRadius: number,
  globalScale = 1,
  activeKinds?: AttentionKeyKind[],
): [number, number, number] {
  const len =
    Math.hypot(hostWorld[0], hostWorld[1], hostWorld[2]) || innerRadius
  const targetR = shellRadiusForKind(
    kind,
    innerRadius,
    globalScale,
    activeKinds,
  )
  const s = targetR / len
  return [hostWorld[0] * s, hostWorld[1] * s, hostWorld[2] * s]
}

export function newPanelChildDoorKey(parentKey: string, k: number): string {
  return `${parentKey}|panel|k${k}`
}

