  // book 正文：从 index 读 T
  let face = faceText
  if (keyKind === 'book') {
    const chunk = input.bookIndex.chunks.find((c) => c.key === key)
    face = chunk?.content?.trim() || ''
    hostWorld = bookKeyHostWorld(key, input.bookIndex, pageCount)
  }

  if (!hostWorld) {
    return {
      key,
      keyKind,
      hostBookKey,
      faceText: face,
      hostWorld: null,
      world: null,
      ok: false,
      note: `${note} · 无宿主世界点`,
    }
  }

  const activeKinds = input.activeKinds?.length
    ? input.activeKinds
    : [keyKind]
  const ratio = adjacentRatioForKind(keyKind, activeKinds)
  const innerR = innerSphereRadius(pageCount)
  const world = panelWorldAnchorFromHost(
    hostWorld,
    keyKind,
    innerR,
    input.globalScale ?? 1,
    activeKinds,
  )

  return {
    key,
    keyKind,
    hostBookKey: hostBookKey ?? (keyKind === 'book' ? key : null),
    faceText: face,
    hostWorld,
    world,
    ok: true,
    note: `${note} · adjacent×${ratio.toFixed(2)} · in[${activeKinds.join(',')}]`,
  }
}

