      fromKeys: [n.historicQueryKey],
      toKey: n.neighbourKey,
    })
  }
  if (llmCallId && minted.length > 0) {
    get().registerLlmCallBatch({
      llmCallId,
      job: 'query',
      memberKeys: minted.map((n) => n.neighbourKey),
      queryKey: nowQueryKey,
      keyKind: 'neighbour',
    })
  }
