/**
 * 常显 key 面板层：按 llmCallId 集合门（一门多格）立在壳上。
 */

import { Html } from '@react-three/drei'
import { useMemo } from 'react'
import { useIndexGate } from '../reasoning/indexGate'
import { useDocuverse } from './store'
import { usePanelSummonStore } from '../reasoning/panelSummonStore'
import { resolveKeyWorldAnchor } from '../reasoning/keyWorldAnchor'
import { AttentionDoorFace } from '../ui/AttentionDoorFace'
import { shortHandle } from '../reasoning/ocrSlot'
import {
  adjacentCallIdsForKey,
} from '../reasoning/turnJobProgress'
import { useAttentionIo } from '../reasoning/attentionIoStore'

function faceTextForKey(key: string): string {
  const a = resolveKeyWorldAnchor({
    key,
    bookIndex: useIndexGate.getState().bookIndex!,
    pageCount: Math.max(useDocuverse.getState().pages.length, 1),
  })
  return a.faceText || key
}

export function KeyPanelLayer() {
  const panels = usePanelSummonStore((s) => s.panels)
  const globalScale = usePanelSummonStore((s) => s.globalScale)
  const shellStep = usePanelSummonStore((s) => s.shellStep)
  const dismissPanel = usePanelSummonStore((s) => s.dismissPanel)
  const toggleEdgeSelect = usePanelSummonStore((s) => s.toggleEdgeSelect)
  const bookIndex = useIndexGate((s) => s.bookIndex)
  const pageCount = useDocuverse((s) => Math.max(s.pages.length, 1))
  const ledger = useAttentionIo((s) => s.llmCallLedger)

  const resolved = useMemo(() => {
    if (!bookIndex || panels.length === 0) return []
    const activeKinds = panels.map((p) => p.keyKind)
    return panels.map((p) => {
      const seedKey = p.memberKeys[0] ?? p.panelId
      const a = resolveKeyWorldAnchor({
        key: seedKey,
        keyKind: p.keyKind,
        bookIndex,
        pageCount,
        globalScale,
        activeKinds,
        shellStep,
        queryKeyForAzimuth: p.queryKey,
      })
      return { summoned: p, anchor: a }
    })
  }, [bookIndex, panels, pageCount, globalScale, shellStep, ledger])

  if (!bookIndex || resolved.length === 0) return null

  return (
    <group>
      {resolved.map(({ summoned, anchor }) => {
        if (!anchor.world) return null
        const members = summoned.memberKeys
        return (
          <Html
            key={summoned.panelId}
            position={anchor.world}
            center
            distanceFactor={18}
            zIndexRange={[160, 0]}
            style={{ pointerEvents: 'auto' }}
          >
            <div
              className="key-panel-live"
              data-kind={anchor.keyKind}
              data-batch={summoned.llmCallId ? '1' : '0'}
              onPointerDown={(e) => e.stopPropagation()}
            >
              <div className="key-panel-live-head">
                <span className="key-panel-live-kind">{anchor.keyKind}</span>
                <span
                  className="key-panel-live-id"
                  title={summoned.llmCallId ?? summoned.panelId}
                >
                  {summoned.llmCallId
                    ? `批×${members.length}`
                    : shortHandle(summoned.panelId)}
                </span>
                <button
                  type="button"
                  className="key-panel-live-x"
                  title="收起"
                  onClick={() => dismissPanel(summoned.panelId)}
                >
                  ×
                </button>
              </div>
              <div className="key-panel-live-batch">
                {members.map((mk, i) => {
                  const cellText =
                    members.length === 1
                      ? anchor.faceText
                      : faceTextForKey(mk).slice(0, 280)
                  return (
                    <AttentionDoorFace
                      key={mk}
                      doorKey={mk}
                      keyKind={anchor.keyKind}
                      faceText={cellText}
                      hostBookKey={anchor.hostBookKey ?? undefined}
                      queryKey={
                        anchor.keyKind === 'query' ? mk : summoned.queryKey
                      }
                    >
                      <button
                        type="button"
                        className="key-panel-live-cell"
                        title="点 key：展开相邻进度边"
                        onClick={() => {
                          const adj = adjacentCallIdsForKey(mk)
                          for (const id of [
                            ...adj.inbound,
                            ...adj.outbound,
                          ]) {
                            toggleEdgeSelect(id)
                          }
                        }}
                      >
                        <span className="key-panel-live-cell-i">{i + 1}</span>
                        <span className="key-panel-live-cell-k">
                          {shortHandle(mk)}
                        </span>
                        <span className="key-panel-live-body">
                          {cellText || '（无正文）'}
                        </span>
                      </button>
                    </AttentionDoorFace>
                  )
                })}
              </div>
            </div>
          </Html>
        )
      })}
    </group>
  )
}

/**
 * 本问进度图（常驻）：queryKey 锚 + 按 LLM 调用序的 out 整批边。
 * ≥2 边选中 → 调取双集合面板；点边切换选中。
 */

import { useMemo, useState } from 'react'
import { useAttentionIo } from '../reasoning/attentionIoStore'
import { usePanelSummonStore } from '../reasoning/panelSummonStore'
import {
  buildTurnJobGraph,
  resolveActiveQueryKey,
} from '../reasoning/turnJobProgress'
import { shortHandle } from '../reasoning/ocrSlot'

export function TurnJobProgressGraph() {
  const ledger = useAttentionIo((s) => s.llmCallLedger)
  const settled = useAttentionIo((s) => s.settledQueries)
  const neighbours = useAttentionIo((s) => s.neighbours)
  const selectedEdgeIds = usePanelSummonStore((s) => s.selectedEdgeIds)
  const toggleEdgeSelect = usePanelSummonStore((s) => s.toggleEdgeSelect)
  const clearEdgeSelect = usePanelSummonStore((s) => s.clearEdgeSelect)
  const summonSelectedEdges = usePanelSummonStore((s) => s.summonSelectedEdges)
  const summonCallBatch = usePanelSummonStore((s) => s.summonCallBatch)
  const [hint, setHint] = useState('')

  const graph = useMemo(() => {
    void ledger
    void settled
    void neighbours
    return buildTurnJobGraph(resolveActiveQueryKey())
  }, [ledger, settled, neighbours])

  if (!graph.queryKeyNow && graph.edges.length === 0) {
    return (
      <div className="turn-progress" role="status">
        <div className="turn-progress-head">本问进度</div>
        <div className="turn-progress-empty">尚无 queryKey · 提问后出现咬尾/撬开边</div>
      </div>
    )
  }

  const qkNodes = graph.nodes.filter((n) => n.kind === 'queryKey')
  const jobNodes = graph.nodes.filter((n) => n.kind === 'job')

  return (
    <div className="turn-progress" role="navigation" aria-label="本问进度拓扑">
      <div className="turn-progress-head">
        <span className="turn-progress-title">本问进度</span>
        <span className="turn-progress-meta">
          {shortHandle(graph.queryKeyNow)} · 边×{graph.edges.length} · 已选
          {selectedEdgeIds.length}
        </span>
      </div>

      <div className="turn-progress-qk">
        {qkNodes.map((n) =>
          n.kind === 'queryKey' ? (
            <span
              key={n.id}
              className={`turn-progress-chip qk ${n.role}`}
              title={n.queryKey}
            >
              {n.role === 'now' ? 'now' : 'hist'} · {shortHandle(n.queryKey)}
            </span>
          ) : null,
        )}
      </div>

      <div className="turn-progress-jobs">
        {jobNodes.map((n) =>
          n.kind === 'job' ? (
            <span
              key={n.id}
              className={`turn-progress-chip job ${n.status}`}
              title={n.job}
            >
              {n.job}
            </span>
          ) : null,
        )}
      </div>

      <div className="turn-progress-edges">
        {graph.edges.map((e) => {
          const on = selectedEdgeIds.includes(e.llmCallId)
          return (
            <button
              key={e.id}
              type="button"
              className={`turn-progress-edge${on ? ' on' : ''}`}
              title={`${e.llmCallId}\n${e.memberKeys.join('\n')}`}
              onClick={() => toggleEdgeSelect(e.llmCallId)}
              onDoubleClick={() => summonCallBatch(e.llmCallId)}
            >
              <span className="turn-progress-edge-job">{e.job}</span>
              <span className="turn-progress-edge-kind">{e.keyKind}</span>
              <span className="turn-progress-edge-n">×{e.memberKeys.length}</span>
            </button>
          )
        })}
        {graph.edges.length === 0 && (
          <span className="turn-progress-empty">本问尚无 LLM 调用批</span>
        )}
      </div>

      <div className="turn-progress-actions">
        <button
          type="button"
          className="corpus-chip"
          disabled={selectedEdgeIds.length < 2}
          onClick={() => {
            const r = summonSelectedEdges()
            setHint(r.note)
          }}
        >
          跳转双面板（≥2边）
        </button>
        <button
          type="button"
          className="corpus-chip"
          onClick={() => {
            clearEdgeSelect()
            setHint('')
          }}
        >
          清选
        </button>
        {hint && <span className="turn-progress-hint">{hint}</span>}
      </div>
    </div>
  )
}

/**
 * 常显 key 面板层：按 llmCallId 集合门（一门多格）立在壳上。
 */

import { Html } from '@react-three/drei'
import { useMemo } from 'react'
import { useIndexGate } from '../reasoning/indexGate'
import { useDocuverse } from './store'
import { usePanelSummonStore } from '../reasoning/panelSummonStore'
import { resolveKeyWorldAnchor } from '../reasoning/keyWorldAnchor'
import { AttentionDoorFace } from '../ui/AttentionDoorFace'
import { shortHandle } from '../reasoning/ocrSlot'
import { adjacentCallIdsForKey } from '../reasoning/turnJobProgress'

export function KeyPanelLayer() {
  const panels = usePanelSummonStore((s) => s.panels)
  const globalScale = usePanelSummonStore((s) => s.globalScale)
  const shellStep = usePanelSummonStore((s) => s.shellStep)
  const dismissPanel = usePanelSummonStore((s) => s.dismissPanel)
  const toggleEdgeSelect = usePanelSummonStore((s) => s.toggleEdgeSelect)
  const bookIndex = useIndexGate((s) => s.bookIndex)
  const pageCount = useDocuverse((s) => Math.max(s.pages.length, 1))

  const resolved = useMemo(() => {
    if (!bookIndex || panels.length === 0) return []
    const activeKinds = panels.map((p) => p.keyKind)
    return panels.map((p) => {
      const seedKey = p.memberKeys[0] ?? p.panelId
      const a = resolveKeyWorldAnchor({
        key: seedKey,
        keyKind: p.keyKind,
        bookIndex,
        pageCount,
        globalScale,
        activeKinds,
        shellStep,
        queryKeyForAzimuth: p.queryKey,
      })
      const memberFaces = p.memberKeys.map((mk) => {
        if (mk === seedKey) return { key: mk, text: a.faceText }
        const m = resolveKeyWorldAnchor({
          key: mk,
          keyKind: p.keyKind,
          bookIndex,
          pageCount,
          globalScale,
          activeKinds,
          shellStep,
          queryKeyForAzimuth: p.queryKey,
        })
        return { key: mk, text: m.faceText }
      })
      return { summoned: p, anchor: a, memberFaces }
    })
  }, [bookIndex, panels, pageCount, globalScale, shellStep])

  if (!bookIndex || resolved.length === 0) return null

  return (
    <group>
      {resolved.map(({ summoned, anchor, memberFaces }) => {
        if (!anchor.world) return null
        return (
          <Html
            key={summoned.panelId}
            position={anchor.world}
            center
            distanceFactor={18}
            zIndexRange={[160, 0]}
            style={{ pointerEvents: 'auto' }}
          >
            <div
              className="key-panel-live"
              data-kind={anchor.keyKind}
              data-batch={summoned.llmCallId ? '1' : '0'}
              onPointerDown={(e) => e.stopPropagation()}
            >
              <div className="key-panel-live-head">
                <span className="key-panel-live-kind">{anchor.keyKind}</span>
                <span
                  className="key-panel-live-id"
                  title={summoned.llmCallId ?? summoned.panelId}
                >
                  {summoned.llmCallId
                    ? `批×${memberFaces.length}`
                    : shortHandle(summoned.panelId)}
                </span>
                <button
                  type="button"
                  className="key-panel-live-x"
                  title="收起"
                  onClick={() => dismissPanel(summoned.panelId)}
                >
                  ×
                </button>
              </div>
              <div className="key-panel-live-batch">
                {memberFaces.map((mf, i) => (
                  <AttentionDoorFace
                    key={mf.key}
                    doorKey={mf.key}
                    keyKind={anchor.keyKind}
                    faceText={mf.text}
                    hostBookKey={anchor.hostBookKey ?? undefined}
                    queryKey={
                      anchor.keyKind === 'query' ? mf.key : summoned.queryKey
                    }
                  >
                    <button
                      type="button"
                      className="key-panel-live-cell"
                      title="点 key：展开相邻进度边"
                      onClick={() => {
                        const adj = adjacentCallIdsForKey(mf.key)
                        for (const id of [...adj.inbound, ...adj.outbound]) {
                          toggleEdgeSelect(id)
                        }
                      }}
                    >
                      <span className="key-panel-live-cell-i">{i + 1}</span>
                      <span className="key-panel-live-cell-k">
                        {shortHandle(mf.key)}
                      </span>
                      <span className="key-panel-live-body">
                        {mf.text?.slice(0, 280) || '（无正文）'}
                      </span>
                    </button>
                  </AttentionDoorFace>
                ))}
              </div>
            </div>
          </Html>
        )
      })}
    </group>
  )
}

